export class Product {
  private reservedStock: number;

  constructor(
    readonly id: string,
    readonly name: string,
    private totalStock: number
  ) {
    this.reservedStock = 0;
  }

  getAvailableStock(): number {
    return this.totalStock - this.reservedStock;
  }

  getTotalStock(): number {
    return this.totalStock;
  }

  getReservedStock(): number {
    return this.reservedStock;
  }

  canReserve(quantity: number): boolean {
    return this.getAvailableStock() >= quantity;
  }

  reserve(quantity: number): void {
    if (!this.canReserve(quantity)) {
      throw new Error(`Insufficient stock for product ${this.id}`);
    }
    this.reservedStock += quantity;
  }

  release(quantity: number): void {
    this.reservedStock = Math.max(0, this.reservedStock - quantity);
  }
}

